import ezdxf, glob

for path in sorted(glob.glob('drawings/*.dxf')):
    print('='*80)
    print('DXF:', path)
    doc = ezdxf.readfile(path)
    msp = doc.modelspace()
    texts = []
    for e in msp:
        if e.dxftype() == 'TEXT':
            p = e.dxf.insert
            texts.append((round(p.y, 1), round(p.x, 1), e.dxf.layer, e.dxf.text))
        elif e.dxftype() == 'MTEXT':
            p = e.dxf.insert
            texts.append((round(p.y, 1), round(p.x, 1), e.dxf.layer, e.text))
        elif e.dxftype() == 'INSERT':
            p = e.dxf.insert
            attribs = {a.dxf.tag: a.dxf.text for a in e.attribs}
            texts.append((round(p.y, 1), round(p.x, 1), e.dxf.layer, f'BLOCK:{e.dxf.name} {attribs}'))
    for y, x, layer, t in sorted(texts, key=lambda item: (-item[0], item[1])):
        print(f'  ({x:6.1f}, {y:6.1f}) [{layer}] {t}')
"

